patch_animation_effects.code:
const response = await client.animationEffects.patchAnimationEffects({
    animation_effects: {
        page_transition: {animation_before_entering_new_page: true},
        image_lazy_effect: {blog_list_image_lazy_effect: true},
    },
});
const settings = response.map.animation_effects;
console.log(settings.page_transition.animation_before_entering_new_page);
console.log(settings.image_lazy_effect.blog_list_image_lazy_effect);

